-- Migration 12: inline product image blobs stored in database

-- Add blob columns to product_images
alter table public.product_images
  alter column image_url drop not null,
  add column if not exists image_data text,
  add column if not exists image_mime text default 'image/svg+xml';

-- Reset any existing gallery rows so we can reseed with blobs
truncate table public.product_images restart identity;

-- Inline SVG placeholders (base64) keyed by brand
with brand_art as (
  select * from (values
    ('Apple', 'data:image/svg+xml;base64,'),
    ('Dell',   'data:image/svg+xml;base64,'),
    ('Lenovo','data:image/svg+xml;base64,'),
    ('HP',    'data:image/svg+xml;base64,'),
    ('ASUS',  'data:image/svg+xml;base64,'),
    ('MSI',   'data:image/svg+xml;base64,'),
    ('Razer', 'data:image/svg+xml;base64,'),
    ('Acer',  'data:image/svg+xml;base64,'),
    ('Samsung','data:image/svg+xml;base64,'),
    ('LG',    'data:image/svg+xml;base64,'),
    ('Default','data:image/svg+xml;base64,')
  ) as t(brand, data)
),
chosen as (
  select p.id,
         coalesce(b.data, (select data from brand_art where brand = 'Default')) as data
  from public.products p
  left join brand_art b on lower(b.brand) = lower(p.brand)
)
insert into public.product_images (product_id, image_url, image_data, image_mime, display_order, is_primary)
select id, null, data, 'image/svg+xml', 0, true
from chosen;
